package vn.iotstar.controller.admin;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import vn.iotstar.entity.User;import vn.iotstar.service.*;import vn.iotstar.service.impl.*;import java.io.IOException;
@WebServlet("/admin/account/add") public class AccountAddController extends HttpServlet{private final UserService s=new UserServiceImpl();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{if(!AdminAuth.requireAdmin(r,p))return;r.getRequestDispatcher("/views/admin/add-account.jsp").forward(r,p);}protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{if(!AdminAuth.requireAdmin(r,p))return;r.setCharacterEncoding("UTF-8");try{String username=r.getParameter("username").trim(),email=r.getParameter("email").trim(),phone=r.getParameter("phone").trim();if(s.checkExistUsername(username)||s.checkExistEmail(email)||s.checkExistPhone(phone))throw new IllegalArgumentException("Username, email hoặc số điện thoại đã tồn tại");User u=new User(email,username,r.getParameter("fullname"),r.getParameter("password"),null,Integer.parseInt(r.getParameter("roleid")),phone,new java.sql.Date(System.currentTimeMillis()));s.insert(u);p.sendRedirect(r.getContextPath()+"/admin/account/list");}catch(Exception e){r.setAttribute("error",e.getMessage());doGet(r,p);}}}
